// --- CUSTOM MIDDLEWARE EXAMPLE ---

// 1. Defining a Middleware function
const securityGuard = (req, res, next) => {
  console.log(`[Middleware Check]: User requesting ${req.url}`);

  const hasTicket = true;

  if (hasTicket) {
    console.log("Ticket valid! Opening the door...");
    next(); // Pass control to the next function!
  } else {
    // Stop the assembly line! Do not call next()!
    console.log("No ticket. Kicking user out.");
    // res.status(403).send('Forbidden');
  }
};

